package org.sleepwell.app;
import android.app.*;import android.content.Intent;import android.os.*;import android.view.View;import android.widget.LinearLayout;import java.util.*;
/** User-controlled deidentified signal export, without an anonymity or scientific-validity promise. */
public final class ResearchExportActivity extends Activity implements ResearchExportJob.Observer {
 private ResearchExportJob job;private Dialog window;
 @Override public void onCreate(Bundle saved){super.onCreate(saved);RecordUi.review(this);Object retained=getLastNonConfigurationInstance();int days=saved==null?7:saved.getInt("days",7);job=retained instanceof ResearchExportJob?(ResearchExportJob)retained:new ResearchExportJob(getApplicationContext(),Records.factory,days,saved!=null);job.observe(this);}
 @Override public Object onRetainNonConfigurationInstance(){return job;}
 @Override public void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);out.putInt("days",job.state().days);}
 public void changed(ResearchExportJob.State state){if(isDestroyed())return;LinearLayout body=Design.page(this,false,null,n->{});RecordUi.label(this,body);RecordUi.header(body,"Export research signals",this::finish);Design.space(body,12);View chooseWindow=Design.item(body,"calendar","Record window",state.days+" days",()->{if(window!=null&&window.isShowing())return;int[] days={7,30,90};int selected=state.days==7?0:state.days==30?1:2;window=SleepPicker.choices(this,"Record window",new String[]{"Last 7 days","Last 30 days","Last 90 days"},selected,n->job.prepare(days[n]));});RecordUi.enabled(chooseWindow,!state.busy());Design.space(body,12);Design.text(body,"Relative movement epochs, signal quality and gap intervals from closed local phone/sonar recordings.",14,400,Design.MUTED);Design.space(body,12);ResearchSignals.Snapshot snapshot=state.snapshot;if(snapshot!=null){Design.item(body,"moon","Selected nights",""+snapshot.nights,null);Design.item(body,"wave","Exported epochs",""+snapshot.epochs,null);Design.item(body,"file","Staged size",android.text.format.Formatter.formatShortFileSize(this,snapshot.bytes),null);Design.item(body,"info","Rejected nights",""+(snapshot.candidates-snapshot.nights),null);Design.text(body,snapshot.unknown+" unknown epochs rejected · "+snapshot.excluded+" partial/outside-coverage epochs excluded",12,400,Design.MUTED);if(!snapshot.rejected.isEmpty()){Design.space(body,8);for(Map.Entry<String,Integer> item:snapshot.rejected.entrySet())Design.text(body,rejection(item.getKey())+": "+item.getValue(),12,400,Design.MUTED);}}
 Design.space(body,16);Design.text(body,"Fresh random IDs and within-night offsets replace dates, clocks, zones and database IDs. Movement is normalized within each night; magnitudes are not comparable between nights or sensors.",13,400,Design.MUTED);Design.space(body,12);Design.text(body,"No notes, tags, ratings, diary, alarms, audio, labels, credentials, device IDs or coordinates. No validated sleep-stage or medical measurements.",13,400,Design.MUTED);Design.space(body,12);Design.text(body,"Not guaranteed anonymous: durations, gaps and signal patterns may still identify you. You choose the destination. Nothing is automatically uploaded or submitted.",14,600,Design.BROWN);if(!state.message.isEmpty()){Design.space(body,12);Design.text(body,state.message,13,500,state.phase==ResearchExportJob.Phase.ERROR?NightDialTokens.NEGATIVE:Design.MUTED);}LinearLayout footer=RecordUi.footer(body);boolean ready=!state.busy()&&snapshot!=null&&snapshot.nights>0;View save=Design.button(footer,state.phase==ResearchExportJob.Phase.WRITING?"Saving…":"Save reviewed signal ZIP",true,this::choose);RecordUi.enabled(save,ready);if(state.phase==ResearchExportJob.Phase.PREPARING)Design.text(footer,"Preparing a private snapshot…",13,500,Design.MUTED);if(state.phase!=ResearchExportJob.Phase.CHOOSING)Design.button(footer,state.busy()?"Cancel export":"Close",false,this::finish);}
 private static String rejection(String reason){switch(reason){case "not_local_phone_tracking":return "Manual/imported or other sources";case "unknown_sensor":return "Unknown sensor";case "unsupported_sensor_metadata":return "Unsupported sensor metadata";case "unknown_or_changed_clock_bounds":return "Unknown or changed clock bounds";case "no_eligible_coverage":return "No eligible coverage";case "no_valid_measured_epochs":return "No valid measured epochs";default:return "Unreadable records";}}
 private void choose(){if(!job.choose())return;try{startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("application/zip").putExtra(Intent.EXTRA_TITLE,"SleepWell-relative-signals.zip"),job.choiceRequest);}catch(android.content.ActivityNotFoundException unavailable){job.cancelChoice();SleepPicker.message(this,"No document picker","Enable Android Files to choose a save location.");}}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=job.choiceRequest)return;if(result!=RESULT_OK||data==null||data.getData()==null)job.cancelChoice();else job.write(data.getData());}
 @Override protected void onDestroy(){if(window!=null)window.dismiss();job.detach(this);if(!isChangingConfigurations())job.close();super.onDestroy();}
 @Override protected void onPostResume(){super.onPostResume();RecordUi.lightBars(this);}
 @Override public void onWindowFocusChanged(boolean focus){super.onWindowFocusChanged(focus);if(focus)RecordUi.lightBars(this);}
}
